<script lang="ts">
  import { browser } from '$app/environment';
  import Icon from '$lib/components/Icon.svelte';
  import LineChart from '$lib/components/LineChart.svelte';
  import MetricCard from '$lib/components/MetricCard.svelte';
  import { adminOrderSeries, adminRevenueSeries, adminMetrics, adminReportCategories, adminCounts, auditEvents, catalogueCategories, moderationQueue, vendorApplications } from '$lib/stores/admin';
  let range='Last 30 days';

  function exportCsv() {
    if (!browser) return;
    const rows=[['Category','GMV','Paid items','Share'],...$adminReportCategories.map((item)=>[item.name,item.gmv,item.orders,item.share])];
    const csv=rows.map((row)=>row.map((value)=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\n');
    const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='assetguru-marketplace-report.csv';link.click();URL.revokeObjectURL(url);
  }
</script>

<svelte:head><title>Marketplace reports — AssetGuru Admin</title></svelte:head>
<header class="admin-page-head"><div><span class="eyebrow">Marketplace intelligence</span><h1>Reports & <span class="gradient-text">insights.</span></h1><p>Verified commercial performance and operational workload. Analytics that are not yet instrumented remain explicitly empty.</p></div><div class="admin-head-actions"><select class="admin-select" bind:value={range}><option>Last 30 days</option></select><button class="button button-secondary" type="button" onclick={exportCsv} disabled={!$adminReportCategories.length}><Icon name="download" size={18}/> Export CSV</button></div></header>

<div class="metrics"><MetricCard label="Gross merchandise value" value={`£${$adminMetrics.gmv.toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})}`} delta="Completed items" icon="chart" tone="magenta"/><MetricCard label="Marketplace revenue" value={`£${$adminMetrics.marketplaceRevenue.toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})}`} delta="Recorded commission" icon="tag" tone="cyan"/><MetricCard label="Completed orders" value={$adminMetrics.orders.toLocaleString('en-GB')} delta={`£${$adminMetrics.averageOrder.toFixed(2)} average`} icon="cart" tone="green"/><MetricCard label="Active vendors" value={$adminMetrics.activeVendors.toLocaleString('en-GB')} delta={`${$adminCounts.vendors} awaiting review`} icon="store" tone="violet"/></div>

<div class="reports-grid">
  <section class="admin-panel glass performance"><div class="admin-panel-head"><div><span class="eyebrow">Revenue trend</span><h2>GMV and order velocity</h2><p>{range} · real completed order records.</p></div></div><LineChart values={$adminRevenueSeries} secondary={$adminOrderSeries} primaryLabel="GMV" secondaryLabel="Orders" height={255}/><div class="performance-foot"><span><b>£{$adminMetrics.averageOrder.toFixed(2)}</b><small>Average order</small></span><span><b>{$adminMetrics.paidItems}</b><small>Paid items</small></span><span><b>{$adminMetrics.refundRate.toFixed(2)}%</b><small>Refunded item rate</small></span><span><b>{$adminMetrics.averageRating ? $adminMetrics.averageRating.toFixed(2) : '—'}</b><small>Average rating</small></span></div></section>

  <section class="admin-panel glass quality"><div class="admin-panel-head"><div><span class="eyebrow">Trust metrics</span><h2>Marketplace quality</h2></div></div><div class="score"><strong>{$adminMetrics.averageRating ? $adminMetrics.averageRating.toFixed(1) : '—'}</strong><span><b>Published review average</b><small>{$adminMetrics.averageRating ? 'Buyer ratings currently recorded' : 'No published reviews yet'}</small></span></div>{#each [['Published products',`${$adminMetrics.publishedProducts}`,Math.min(100,$adminMetrics.publishedProducts*10)],['Approved vendors',`${$adminMetrics.activeVendors}`,Math.min(100,$adminMetrics.activeVendors*10)],['Moderation queue',`${$adminCounts.moderation}`,Math.max(0,100-$adminCounts.moderation*10)],['Audit records loaded',`${$auditEvents.length}`,Math.min(100,$auditEvents.length)]] as item}<div class="quality-row"><span><b>{item[0]}</b><small>{item[1]}</small></span><div><i style={`width:${item[2]}%`}></i></div></div>{/each}</section>

  <section class="admin-panel glass categories"><div class="admin-panel-head"><div><span class="eyebrow">Category performance</span><h2>Demand by catalogue area</h2></div></div>{#if $adminReportCategories.length}<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Category</th><th>GMV</th><th>Paid items</th><th>Share</th></tr></thead><tbody>{#each $adminReportCategories as category}<tr><td><strong>{category.name}</strong></td><td>£{category.gmv.toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})}</td><td>{category.orders.toLocaleString('en-GB')}</td><td><div class="share"><i style={`width:${category.share}%`}></i><span>{category.share}%</span></div></td></tr>{/each}</tbody></table></div>{:else}<div class="empty-report"><Icon name="grid" size={25}/><span><b>No category sales yet</b><small>Category GMV will appear after completed purchases.</small></span></div>{/if}</section>

  <section class="admin-panel glass search"><div class="admin-panel-head"><div><span class="eyebrow">Discovery demand</span><h2>Search opportunities</h2><p>Production search-event telemetry has not been enabled in this sprint.</p></div></div><div class="empty-report"><Icon name="search" size={25}/><span><b>No search events recorded</b><small>No invented query or click-through data is shown.</small></span></div><a class="button button-secondary" href="/admin/catalogue">Manage discovery</a></section>

  <section class="admin-panel glass funnel"><div class="admin-panel-head"><div><span class="eyebrow">Commercial output</span><h2>Completed transactions</h2></div></div>{#each [['Completed orders',$adminMetrics.orders,100],['Paid order items',$adminMetrics.paidItems,$adminMetrics.orders ? Math.min(100,$adminMetrics.paidItems/$adminMetrics.orders*50) : 0],['Published products',$adminMetrics.publishedProducts,Math.min(100,$adminMetrics.publishedProducts*10)],['Approved vendors',$adminMetrics.activeVendors,Math.min(100,$adminMetrics.activeVendors*10)]] as step,index}<div class="funnel-row"><span><i>{index+1}</i><b>{step[0]}</b></span><div><i style={`width:${Math.max(Number(step[2]),step[1] ? 6 : 0)}%`}></i></div><strong>{Number(step[1]).toLocaleString('en-GB')}</strong><small>live</small></div>{/each}</section>

  <section class="admin-panel glass operations"><div class="admin-panel-head"><div><span class="eyebrow">Operations</span><h2>Current workload</h2></div></div><div class="ops-grid">{#each [['Moderation items',$adminCounts.moderation,'Open'],['Vendor applications',$adminCounts.vendors,'Open'],['Admin cases',$adminCounts.cases,'Open'],['Urgent cases',$adminCounts.urgent,$adminCounts.urgent ? 'Action' : 'Clear'],['Categories',$catalogueCategories ? $catalogueCategories.length : 0,'Configured'],['Audit events',$auditEvents ? $auditEvents.length : 0,'Loaded']] as item}<span><small>{item[0]}</small><b>{item[1]}</b><em>{item[2]}</em></span>{/each}</div></section>
</div>
